(6467103, 811767, 92577, '<td valign="top">shame this didn''t score higher - it''s a very cool idea</td>', 'shame this didn''t score higher - it''s a very cool idea', '2011-07-10 19:03:05.000000', NULL, 0),
(7256234, 810807, 23484, '<td valign="top">I like the b&amp;w conversion and I like that the places that are in focus are not located in one spot. You have to look around.</td>', 'I like the b&w conversion and I like that the places that are in focus are not located in one spot. You have to look around.', '2014-08-28 16:02:53.000000', NULL, 0);
